4	
5	public class TransactionBehavior<TRequest, TResponse> : IPipelineBehavior<TRequest, TResponse> where TRequest : IRequest<TResponse>
6	{
7	    private readonly ILogger<TransactionBehavior<TRequest, TResponse>> _logger;
8	    private readonly OrderingContext _dbContext;
9	    private readonly IOrderingIntegrationEventService _orderingIntegrationEventService;
10	
11	    public TransactionBehavior(OrderingContext dbContext,
12	        IOrderingIntegrationEventService orderingIntegrationEventService,
13	        ILogger<TransactionBehavior<TRequest, TResponse>> logger)
14	    {
15	        _dbContext = dbContext ?? throw new ArgumentException(nameof(OrderingContext));
16	        _orderingIntegrationEventService = orderingIntegrationEventService ?? throw new ArgumentException(nameof(orderingIntegrationEventService));
17	        _logger = logger ?? throw new ArgumentException(nameof(ILogger));
18	    }
19	
20	    public async Task<TResponse> Handle(TRequest request, RequestHandlerDelegate<TResponse> next, CancellationToken cancellationToken)
21	    {
22	        var response = default(TResponse);
23	        var typeName = request.GetGenericTypeName();
24	
25	        try
26	        {
27	            if (_dbContext.HasActiveTransaction)
28	            {
29	                return await next();
30	            }
31	
32	            var strategy = _dbContext.Database.CreateExecutionStrategy();
33	
34	            await strategy.ExecuteAsync(async () =>
35	            {
36	                Guid transactionId;
37	
38	                await using var transaction = await _dbContext.BeginTransactionAsync();
39	                using (_logger.BeginScope(new List<KeyValuePair<string, object>> { new("TransactionContext", transaction.TransactionId) }))
40	                {
41	                    _logger.LogInformation("Begin transaction {TransactionId} for {CommandName} ({@Command})", transaction.TransactionId, typeName, request);
42	
43	                    response = await next();
44	
45	                    _logger.LogInformation("Commit transaction {TransactionId} for {CommandName}", transaction.TransactionId, typeName);
46	
47	                    await _dbContext.CommitTransactionAsync(transaction);
48	
49	                    transactionId = transaction.TransactionId;
50	                }
51	
52	                await _orderingIntegrationEventService.PublishEventsThroughEventBusAsync(transactionId);
53	            });
54	
55	            return response;
56	        }
57	        catch (Exception ex)
58	        {
59	            _logger.LogError(ex, "Error Handling transaction for {CommandName} ({@Command})", typeName, request);
60	
61	            throw;
62	        }
63	    }
64	}
